import * as THREE from 'three/webgpu';
import { TextureNode, MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Configuration defaults
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const textContent = config.textContent || 'Collection';
  const position = config.scenePosition || { x: 0, y: 3, z: 0 };

  // Load texture for plane background
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane mesh with node material
  const planeGeo = new THREE.PlaneGeometry(4, 2);
  const planeMaterial = new MeshBasicNodeMaterial({
    colorNode: new TextureNode(texture),
    side: THREE.DoubleSide
  });
  const planeMesh = new THREE.Mesh(planeGeo, planeMaterial);
  group.add(planeMesh);

  // Create text mesh using font atlas
  const text = Array.isArray(textContent) ? textContent[0] : String(textContent);
  const textMesh = ctx.fontAtlas.create({
    text: text,
    font: 'Lora',
    size: 0.34,
    weight: 400,
    color: new THREE.Color('#16161d'),
    align: 'center'
  });
  textMesh.position.z = 0.1;
  group.add(textMesh);

  // Apply scene position
  const { x = 0, y = 3, z = 0 } = position;
  group.position.set(x, y, z);

  // Setup handlers and cleanup
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    planeGeo.dispose();
    planeMaterial.dispose();
    texture.dispose();
  };

  return group;
}
